import {bindIronReaction} from './iron-paired-reaction.js';
import {predictionMarkup,mountPrediction,hasPrediction,clearPrediction} from './prediction.js';
import {bindDrop} from './direct-manipulation.js';
import {prepScenes,affinityOrder,affinityNames,prepQuizzes,freshPrep,restorePrep,prepReady,prepMastered,checkAffinity} from './forge-prep-model.js';
import {affinityReference,pairedRedoxPrinciple,ironRedoxScene} from './oxygen-affinity.js';
const key='lost-forge-preparation-v1';
const titles=['沒有火焰，也算氧化？','碳為什麼能把鐵找回來？','氧化，一定伴隨還原'];
// A pointer drag can also dispatch click; keep its result feedback intact.
function distinguishDrag(item){let origin=null,moved=false;item.addEventListener('pointerdown',e=>{origin=[e.clientX,e.clientY];moved=false;});item.addEventListener('pointermove',e=>{if(origin&&Math.hypot(e.clientX-origin[0],e.clientY-origin[1])>4)moved=true;});item.addEventListener('pointerup',()=>{origin=null;});item.addEventListener('click',e=>{if(moved){e.preventDefault();e.stopImmediatePropagation();moved=false;}},true);}
const sceneArt=id=>`<div class="prep-scene-art prep-art-${id}" aria-hidden="true"><span>${({burn:'炭火近觀',rust:'鏽層近觀',breath:'細胞內部示意',ice:'冰水共存'})[id]}</span></div>`;
export function mountForgePrep(root){
 let s=freshPrep(),cleanups=[],selected=null,status='',saved=true;
 try{s=restorePrep(JSON.parse(localStorage.getItem(key)||'null'));}catch{saved=false;}
 const save=()=>{try{localStorage.setItem(key,JSON.stringify(s));}catch{saved=false;}root.dispatchEvent(new CustomEvent('prep-progress',{bubbles:true,detail:[0,1,2].filter(i=>prepMastered(s,i)).length}));};
 const say=text=>{status=text;root.querySelector('[data-prep-status]').textContent=text;};
 function render(){
  cleanups.forEach(f=>f());cleanups=[];selected=null;
  const i=s.tab,q=prepQuizzes[i],ready=prepReady(s,i),mastered=prepMastered(s,i),predictionId='prep-'+i;
  root.innerHTML=`<header class="chapter-header"><div class="chapter-kicker"><span>工坊試煉｜先認識氧化</span><span>01</span></div><h2 id="forge-prep-title">先弄懂氧，才找得回金屬</h2><p class="core-question">認識氧化、對氧活性與氧的轉移；到生活中找配對，再到樣本架驗證。</p></header><div class="chapter-body"><div class="prep-conversation"><span class="story-portrait story-portrait--${i===0?'kui':'grandpa'}" data-expression="${i===0?'curious':'thinking'}" aria-hidden="true"></span><p><b>${i===0?'小葵':'阿公'}</b>${['「木炭有火，鐵鏽沒有火。它們都和氧有關嗎？」','「先看誰比較容易和氧結合。碳排在鐵的哪一邊？能幫我們把鐵找回來嗎？」','「氧不會憑空消失。要找出誰被還原，就一起找出誰被氧化。」'][i]}</p></div><div class="prep-tabs" role="group" aria-label="三張工坊試煉">${titles.map((t,j)=>`<button data-prep-tab="${j}" aria-pressed="${i===j}"><span>${prepMastered(s,j)?'✓':String.fromCharCode(65+j)}</span><b>${['辨認氧化','對氧活性大小','氧化與還原成對'][j]}</b></button>`).join('')}</div><section class="prep-studio" aria-label="${titles[i]}"><header class="prep-studio-head"><div><small>WORKSHOP / ${String.fromCharCode(65+i)}</small><h3>${titles[i]}</h3></div><div class="prep-studio-tools"><button type="button" class="card-reset card-reset-inverse" data-prep-reset aria-label="重設試煉 ${String.fromCharCode(65+i)}：${titles[i]}">↺ 重設本卡</button><span>${i===0?s.sorted.length+' / 4 份紀錄':i===1?s.order.length+' / 4 個位置':(s.reaction==='iron'?s.ironPairs.length+' / 3 個氧':s.moved.length+' / 2 個氧')}</span></div></header>${predictionMarkup(predictionId)}<div data-prediction-activity inert>${i===0?classification():i===1?ranking():redoxExamples()}</div><div data-prediction-review hidden></div><p class="prep-live" data-prep-status role="status">${!hasPrediction(predictionId)?'先觀察場景，再留下上方的猜想，就能開始操作。':status||['先選一張觀察圖卡，再點下方分類；也可以直接拖進分類區。','先點活性表中的元素，和碳比較；再用線索排出鎂、碳、鐵、銅。',s.reaction==='iron'?'按下「開始反應」，追蹤氧如何從氧化鐵移到 CO。':'把 CO₂ 中的兩個氧，拖到尚未接氧的 Mg；也可點氧，再點鎂。'][i]}</p></section><section class="prep-quiz" ${ready&&hasPrediction(predictionId)?'':'hidden'} aria-label="小試身手"><small>小葵的筆記 · 檢查理解</small><h3>${q.question}</h3><div class="prep-answers">${q.options.map((a,j)=>`<button data-prep-answer="${j}" aria-pressed="${s.answers[i]===j}" class="${s.answers[i]===j?(j===q.answer?'correct':'wrong'):''}">${String.fromCharCode(65+j)}　${a}</button>`).join('')}</div><p class="prep-feedback" role="status">${s.answers[i]===null?'':(mastered?'✓ 答對了。':'正確答案是 '+String.fromCharCode(65+q.answer)+'。')+q.reason}</p></section><div class="prep-footer"><button class="text-button" data-prep-reset>重設這張試煉</button><span>${saved?'操作與作答會保存在這台裝置。':'本次可操作；瀏覽器暫時無法保存進度。'}</span>${i<2?`<button class="primary" data-prep-next ${mastered?'':'disabled'}>帶著線索，進入${i===0?'活性排序':'氧的轉移'} →</button>`:`<a class="primary" href="#everyday-redox">02 到生活中找氧化還原 →</a>`}</div></div>`;
  root.querySelectorAll('[data-prep-tab]').forEach(b=>b.onclick=()=>{s.tab=+b.dataset.prepTab;status='';render();save();});
  root.querySelector('[data-prep-next]')?.addEventListener('click',()=>{if(!prepMastered(s,s.tab))return;s.tab++;status='';render();save();root.querySelector('.prep-tabs').scrollIntoView({block:'start',behavior:'instant'});});
  root.querySelectorAll('[data-prep-reset]').forEach(b=>b.onclick=()=>{clearPrediction(predictionId);if(i===0)s.sorted=[];if(i===1){s.order=[];s.referenceElement='Fe';}if(i===2){s.moved=[];s.targets=[];s.ironPairs=[];};s.answers[i]=null;status='已重設這張試煉，可以再試一次。';render();save();root.querySelector('.prep-studio-head [data-prep-reset]').focus({preventScroll:true});});
  root.querySelectorAll('[data-prep-answer]').forEach(b=>b.onclick=()=>{if(!prepReady(s,i))return;s.answers[i]=+b.dataset.prepAnswer;render();save();});
  mountPrediction(root.querySelector('[data-prediction-host]'),predictionId,{activity:root.querySelector('[data-prediction-activity]'),review:root.querySelector('[data-prediction-review]'),observed:i===0?s.sorted.length>0:i===1?s.order.length>0:s.moved.length+s.ironPairs.length>0,onStart:()=>{root.querySelector('[data-prep-status]').textContent=status||'猜想已留下，現在可以操作並收集證據。';root.querySelector('.prep-quiz').hidden=!ready;if(i===0)bindClassification();if(i===1){bindRanking();bindAffinityReference();}if(i===2)bindRedoxExamples();}});
 }
 function classification(){return `<div class="prep-oxidation-intro"><small>先認識一個詞</small><h4>氧化：物質與氧結合</h4><p>這一課先從「得到氧」理解氧化。木炭燃燒、鐵釘生鏽，雖然快慢不同，都有物質與氧結合；冰塊融化只是狀態改變。</p><b>有火焰，不是判斷氧化的唯一線索。</b></div><p class="prep-instruction">把四份觀察，放進合適的紀錄匣。<b>判斷依據是變化，不只是有沒有火。</b></p><div class="prep-scenes">${prepScenes.map(x=>`<button class="prep-observation ${s.sorted.includes(x.id)?'prep-done':''}" data-scene="${x.id}" aria-label="${x.title}" ${s.sorted.includes(x.id)?'disabled':''}>${sceneArt(x.id)}<small>${x.tag}</small><strong>${x.title}</strong><span>${s.sorted.includes(x.id)?'✓ 已歸檔':'抓起圖卡 ↓'}</span></button>`).join('')}</div><div class="prep-bins">${[['fast','劇烈的氧化','短時間，明顯放熱'],['slow','緩慢／分步的氧化','沒有火焰，也在變化'],['physical','物理變化','物質種類沒有改變']].map(([id,title,sub])=>`<button class="prep-bin" data-bin="${id}"><b>${title}</b><small>${sub}</small><div>${prepScenes.filter(x=>x.kind===id&&s.sorted.includes(x.id)).map(x=>`<span>✓ ${x.title}</span>`).join('')||'<span class="prep-empty">放到這裡</span>'}</div></button>`).join('')}</div><div class="prep-evidence">${s.sorted.map(id=>{const x=prepScenes.find(a=>a.id===id);return `<p><b>${x.title}</b>${x.detail}<small>${x.equation}</small></p>`;}).join('')}</div><details class="prep-note"><summary>課本之外，再想一步：光合作用呢？</summary><p>光合作用也涉及氧化還原，但不能把整體簡化成「物質和氧氣結合」。這裡先用得氧、失氧理解燃燒與金屬冶煉；更完整的判斷會涉及電子轉移。</p></details>`;}
 function classify(id,bin){const x=prepScenes.find(a=>a.id===id);if(!x||s.sorted.includes(id))return;if(x.kind!==bin){say(x.title+'應放在「'+({fast:'劇烈的氧化',slow:'緩慢／分步的氧化',physical:'物理變化'})[x.kind]+'」。'+x.detail+' 再放一次，留下你的紀錄。');return;}s.sorted.push(id);status=x.title+'已歸檔。'+x.detail;render();save();}
 function bindClassification(){
  const bins=[...root.querySelectorAll('[data-bin]')];let target=null;
  root.querySelectorAll('[data-scene]:not(:disabled)').forEach(item=>{
   distinguishDrag(item);
   item.onclick=()=>{selected=item.dataset.scene;root.querySelectorAll('[data-scene]').forEach(b=>b.setAttribute('aria-pressed',String(b===item)));say('已選「'+prepScenes.find(x=>x.id===selected).title+'」，點一個紀錄匣。');};
   let reset;reset=bindDrop(item,()=>target||bins[0],{onMove:(_,r)=>{target=bins.find(b=>{const z=b.getBoundingClientRect();return r.left+r.width/2>=z.left&&r.left+r.width/2<=z.right&&r.top+r.height/2>=z.top&&r.top+r.height/2<=z.bottom;})||null;},onDrop:()=>{if(target)classify(item.dataset.scene,target.dataset.bin);reset();target=null;},onMiss:()=>{if(target)classify(item.dataset.scene,target.dataset.bin);else say('圖卡還沒進入紀錄匣，請再拖一次，或點選圖卡後點分類。');reset();target=null;}});cleanups.push(reset);
  });bins.forEach(b=>b.onclick=()=>selected?classify(selected,b.dataset.bin):say('先選一張上方圖卡，再點分類。'));
 }
 function ranking(){return `${affinityReference(s.referenceElement)}<h4 class="prep-sort-heading">換你排：把煉鐵用得上的線索留下</h4><p class="prep-instruction">從對氧活性較大到較小，排出鎂、碳、鐵、銅四個位置。</p><div class="prep-clues"><b>可用線索</b><span>鎂能從 CO₂ 取得氧</span><span>合適高溫下，碳可還原鐵、銅的氧化物</span><span>這組比較中，鐵比銅容易氧化</span></div><div class="prep-affinity-arrow"><span>較容易得氧</span><i></i><span>較不容易得氧</span></div><div class="prep-order">${[0,1,2,3].map(j=>`<button data-order-slot="${j}" class="prep-order-slot ${s.order[j]?'filled':''}" aria-label="第 ${j+1} 個位置${s.order[j]?'，'+affinityNames[s.order[j]]+'，點擊移回':''}"><small>${String(j+1).padStart(2,'0')}</small><b>${s.order[j]||'＋'}</b><span>${s.order[j]?affinityNames[s.order[j]]:'放入元素'}</span></button>`).join('')}</div><div class="prep-elements">${['Cu','Mg','Fe','C'].filter(id=>!s.order.includes(id)).map(id=>`<button class="prep-element prep-element-${id}" data-element="${id}" aria-label="${affinityNames[id]}，放入下一個空位"><b>${id}</b><span>${affinityNames[id]}</span><small>拖入順位 ↑</small></button>`).join('')}</div><div class="prep-rank-tools"><button data-check-order class="primary" ${s.order.length<4?'disabled':''}>檢查排列</button><button data-clear-order class="text-button">重新排列</button></div>${prepReady(s,1)?`<div class="prep-stability"><div><small>元素的一面</small><b>鎂較容易與氧反應</b><p>元素對氧活性較大，較容易得到氧。</p></div><span>⇄</span><div><small>氧化物的一面</small><b>MgO 較難把氧交出去</b><p>與氧的結合較穩定，不代表容易分解。</p></div></div>`:''}`;}
 function placeElement(id,slot){if(s.order.includes(id))return;const next=s.order.length;if(slot!==next){say('先填第 '+(next+1)+' 個位置，再往右排。');return;}s.order.push(id);s.answers[1]=null;status=s.order.length===4?'四個位置放好了。點「檢查排列」，再比較元素與氧化物。':'已放入'+affinityNames[id]+'。繼續向右排列。';render();save();}
 function bindRanking(){const slots=[...root.querySelectorAll('[data-order-slot]')];let target=null;root.querySelectorAll('[data-element]').forEach(item=>{distinguishDrag(item);item.onclick=()=>placeElement(item.dataset.element,s.order.length);let reset;reset=bindDrop(item,()=>target||slots[s.order.length]||slots[3],{onMove:(_,r)=>{target=slots.find(b=>{const z=b.getBoundingClientRect();return r.left+r.width/2>=z.left&&r.left+r.width/2<=z.right&&r.top+r.height/2>=z.top&&r.top+r.height/2<=z.bottom;})||null;},onDrop:()=>{if(target)placeElement(item.dataset.element,+target.dataset.orderSlot);reset();target=null;},onMiss:()=>{if(target)placeElement(item.dataset.element,+target.dataset.orderSlot);else say('請放進順位框；也可以點元素，依序加入。');reset();target=null;}});cleanups.push(reset);});slots.forEach(b=>b.onclick=()=>{const j=+b.dataset.orderSlot;if(j<s.order.length){s.order.splice(j,1);s.answers[1]=null;status='已把這個元素移回候選區。';render();save();}});root.querySelector('[data-clear-order]').onclick=()=>{s.order=[];s.answers[1]=null;status='從較容易得氧的一端重新排起。';render();save();};root.querySelector('[data-check-order]').onclick=()=>say(checkAffinity(s.order)?'✓ Mg ＞ C ＞ Fe ＞ Cu。留得住氧的元素，形成的氧化物通常也較穩定。':'參考順序是 Mg ＞ C ＞ Fe ＞ Cu。再讀線索，點錯位的元素移回後重排。');}
 function bindAffinityReference(){
  root.querySelectorAll('[data-affinity]').forEach(b=>b.onclick=()=>{s.referenceElement=b.dataset.affinity;render();save();root.querySelector('[data-affinity="'+s.referenceElement+'"]').focus({preventScroll:true});});
 }
 function redoxExamples(){return pairedRedoxPrinciple()+'<div class="redox-examples" role="group" aria-label="選擇氧化還原例子">'+[['iron','煉鐵：氧化鐵與 CO'],['magnesium','比較：二氧化碳與鎂']].map(([id,label])=>'<button data-redox-example="'+id+'" aria-pressed="'+(s.reaction===id)+'">'+label+'</button>').join('')+'</div>'+(s.reaction==='iron'?ironRedoxScene(s.ironPairs):transfer())+'<details class="prep-note"><summary>沒有氧轉移的反應，也有氧化還原嗎？</summary><p>有。得氧、失氧是這一課的觀察方式；更一般地，氧化是失去電子，還原是得到電子。電子不會憑空消失，因此兩者必定相伴。</p></details>';}
 function bindRedoxExamples(){
  root.querySelectorAll('[data-redox-example]').forEach(b=>b.onclick=()=>{s.reaction=b.dataset.redoxExample;status='';render();save();root.querySelector('[data-redox-example="'+s.reaction+'"]').focus({preventScroll:true});});
  if(s.reaction==='magnesium'){bindTransfer();return;}
  cleanups.push(bindIronReaction(root.querySelector('[data-iron-reaction]'),()=>{
   s.ironPairs=[0,1,2];status='氧化鐵失去氧，被還原成鐵；CO 得到氧，被氧化成 CO₂。兩者同時發生，氧原子總數不變。';
   render();save();
   // The glossary adds its term primer after rendering; keep the reaction in
   // view once that layout update has finished, without retaining stale work.
   let frame=requestAnimationFrame(()=>{frame=requestAnimationFrame(()=>{
    root.querySelector('[data-iron-reaction]')?.scrollIntoView({block:'start',behavior:'instant'});
    root.querySelector('[data-react]')?.focus({preventScroll:true});
   });});cleanups.push(()=>cancelAnimationFrame(frame));
  }));
 }
 function transfer(){return `<p class="prep-instruction">鎂能取走 CO₂ 中的氧。<b>每移動一個氧，同時觀察兩邊。</b></p><div class="prep-transfer"><div class="prep-donor"><small>氧原本在這裡</small><h4>${s.moved.length===2?'留下碳 C':'二氧化碳 CO₂'}</h4><div class="prep-molecule"><b class="prep-atom carbon">C</b>${[0,1].map(j=>`<button class="prep-atom oxygen oxygen-${j}" data-mg-oxygen="${j}" aria-label="第 ${j+1} 個氧，移到一份尚未接氧的鎂" ${s.moved.includes(j)?'hidden':''}>O</button>`).join('')}</div><p>${s.moved.length===0?'2 個氧等待轉移':s.moved.length===1?'正在追蹤第 1 個氧；不是穩定中間產物':'CO₂ 失去氧 → 被還原'}</p></div><div class="prep-transfer-arrow">氧<br>→</div><div class="prep-receivers"><small>把氧交給鎂</small>${[0,1].map(j=>`<button class="prep-magnesium ${s.targets.includes(j)?'received':''}" data-mg="${j}" aria-label="第 ${j+1} 份鎂的接氧區"><b class="prep-atom metal">Mg</b><span class="prep-atom ${s.targets.includes(j)?'oxygen':'socket'}">${s.targets.includes(j)?'O':'＋'}</span><strong>${s.targets.includes(j)?'MgO · 氧化鎂':'第 '+(j+1)+' 份 Mg'}</strong></button>`).join('')}</div></div><div class="prep-paired"><p><b>失氧這一邊</b>CO₂ → C<span>${s.moved.length?'正在失氧 · 還原':'等待氧離開'}</span></p><i>同一個反應</i><p><b>得氧這一邊</b>Mg → MgO<span>${s.moved.length?'正在得氧 · 氧化':'等待氧到來'}</span></p></div><div class="prep-equation ${s.moved.length===2?'complete':''}"><small>總反應 · 需點燃／合適條件</small><strong>2Mg + CO₂ → 2MgO + C</strong><span>前後都是 2 個 Mg、1 個 C、2 個 O</span></div>${s.moved.length===2?'<div class="prep-metallurgy"><b>從這裡，走向冶煉</b><p>從礦石中提取金屬，稱為冶煉。對氧化物礦石，可在適當條件下讓另一種物質帶走氧，使金屬被還原出來。</p><p>鎂能從 CO₂ 奪氧，不代表碳能反過來還原 MgO。接下來先到 02 觀察物質得到氧，再到 03 驗證碳是不是氧化銅的合適幫手。</p></div>':''}<p class="prep-model-note">粒子轉移示意；球色、大小與路徑不代表實物。逐個移動是為了追蹤收支，並非真實反應機構。僅螢幕模擬。</p>`;}
 function transferOxygen(id,target){if(s.moved.includes(id))return;if(s.targets.includes(target)){say('這份鎂已接到氧，請找另一份鎂。');return;}s.moved.push(id);s.targets.push(target);status=s.moved.length===2?'兩個氧都有去處了：鎂得氧，二氧化碳失氧。氧化與還原相伴發生。':'同一個氧離開 CO₂，也被 Mg 接到。再移動另一個氧，完成總反應。';render();save();}
 function bindTransfer(){const receivers=[...root.querySelectorAll('[data-mg]')];root.querySelectorAll('[data-mg-oxygen]:not([hidden])').forEach(item=>{distinguishDrag(item);const id=+item.dataset.mgOxygen;let target=null;item.onclick=()=>{selected=id;say('已選一個氧，點一份尚未接氧的鎂。');};let reset;reset=bindDrop(item,()=>target||receivers.find(b=>!s.targets.includes(+b.dataset.mg)),{onMove:(_,r)=>{target=receivers.find(b=>{const z=b.getBoundingClientRect();return r.left+r.width/2>=z.left&&r.left+r.width/2<=z.right&&r.top+r.height/2>=z.top&&r.top+r.height/2<=z.bottom;})||null;},onDrop:()=>{if(target)transferOxygen(id,+target.dataset.mg);reset();target=null;},onMiss:()=>{if(target)transferOxygen(id,+target.dataset.mg);else say('氧還沒有進入鎂的接氧區，請再拖一次；也可點氧再點鎂。');reset();target=null;}});cleanups.push(reset);});receivers.forEach(b=>b.onclick=()=>selected===null?say('先點 CO₂ 的一個氧，再點尚未接氧的鎂。'):transferOxygen(selected,+b.dataset.mg));}
 render();save();return ()=>cleanups.forEach(f=>f());
}
